        scanner.nextLine();
        int totalCount = 0;
        int maxLength = 0;
        String inputStr = scanner.nextLine();

        for (int i = 0; i < t; i++) {
            int currentLength = 0;
            int countInParentheses = 0;
            boolean inParentheses = false;

